alter table public.restaurants add column if not exists sector text; alter table public.restaurants add column if not exists onboarding_status text not null default 'READY'; alter table public.restaurants add column if not exists settings jsonb not null default '{}'::jsonb; alter table public.restaurants add column if not exists domain text; alter table public.restaurants add column if not exists phone text; alter table public.restaurants add column if not exists address jsonb not null default '{}'::jsonb; alter table public.restaurants add constraint restaurants_sector_check check (sector is null or sector in ('pizza','kebab','burger','restaurant','snack','boulangerie','sushi','other')); alter table public.restaurants add constraint restaurants_onboarding_status_check check (onboarding_status in ('DRAFT','IMPORTING','REVIEW','READY','PAUSED'));
create table if not exists public.restaurant_members (restaurant_id uuid not null references public.restaurants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'owner', created_at timestamptz not null default now(), primary key (restaurant_id,user_id), constraint restaurant_members_role_check check (role in ('owner','manager','staff'))); alter table public.restaurant_members enable row level security;
create index if not exists restaurant_members_user_idx on public.restaurant_members(user_id); create index if not exists restaurant_members_restaurant_idx on public.restaurant_members(restaurant_id);
create or replace function public.is_restaurant_member(p_restaurant_id uuid, p_roles text[] default array['owner','manager','staff']) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.restaurant_members rm where rm.restaurant_id = p_restaurant_id and rm.user_id = (select auth.uid()) and rm.role = any(p_roles)); $$;
revoke all on function public.is_restaurant_member(uuid,text[]) from public, anon, authenticated; grant execute on function public.is_restaurant_member(uuid,text[]) to authenticated;
create policy restaurant_members_self_select on public.restaurant_members for select to authenticated using (user_id = (select auth.uid()));
create policy restaurant_members_admin_select on public.restaurant_members for select to authenticated using (public.is_restaurant_member(restaurant_id, array['owner','manager']));
create table if not exists public.sector_templates (sector text primary key, label text not null, template jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.sector_templates enable row level security;
create policy sector_templates_public_read on public.sector_templates for select to anon, authenticated using (true);
insert into public.sector_templates(sector,label,template) values ('pizza','Pizza','{"categories":["Pizzas","Menus","Boissons","Desserts"],"option_groups":["Taille","Pâte","Suppléments","Sauces"]}'::jsonb),('kebab','Kebab','{"categories":["Kebabs","Sandwichs","Menus","Boissons","Desserts"],"option_groups":["Viande","Sauce","Suppléments","Formule"]}'::jsonb),('burger','Burger','{"categories":["Burgers","Menus","Accompagnements","Boissons","Desserts"],"option_groups":["Sauce","Suppléments","Formule"]}'::jsonb),('restaurant','Restaurant','{"categories":["Entrées","Plats","Accompagnements","Boissons","Desserts"],"option_groups":["Options","Suppléments"]}'::jsonb),('snack','Snack','{"categories":["Menus","Sandwichs","Burgers","Accompagnements","Boissons","Desserts"],"option_groups":["Viande","Sauce","Suppléments","Formule"]}'::jsonb),('boulangerie','Boulangerie','{"categories":["Pains","Viennoiseries","Pâtisseries","Sandwichs","Boissons"],"option_groups":["Taille","Suppléments"]}'::jsonb),('sushi','Sushi','{"categories":["Sushis","Makis","Plats","Menus","Boissons","Desserts"],"option_groups":["Taille","Sauce","Suppléments"]}'::jsonb),('other','Autre','{"categories":[],"option_groups":[]}'::jsonb) on conflict (sector) do update set label=excluded.label, template=excluded.template, updated_at=now();
create or replace function public.provision_restaurant(p_name text,p_slug text,p_sector text,p_domain text default null) returns public.restaurants language plpgsql security definer set search_path = public as $$ declare r public.restaurants; begin if (select auth.uid()) is null then raise exception 'authentication required'; end if; if p_sector not in ('pizza','kebab','burger','restaurant','snack','boulangerie','sushi','other') then raise exception 'invalid sector'; end if; if length(trim(p_name)) < 2 then raise exception 'invalid name'; end if; if p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'invalid slug'; end if; insert into public.restaurants(name,slug,sector,onboarding_status,domain) values(trim(p_name),lower(p_slug),p_sector,'DRAFT',nullif(trim(p_domain),'')) returning * into r; insert into public.restaurant_members(restaurant_id,user_id,role) values(r.id,(select auth.uid()),'owner'); insert into public.loyalty_programs(restaurant_id,name,is_active,earn_mode,points_per_euro) values(r.id,'Fidélité FOODATOI',false,'points_per_euro',1); return r; exception when unique_violation then raise exception 'restaurant slug or domain already exists'; end; $$;
revoke all on function public.provision_restaurant(text,text,text,text) from public, anon; grant execute on function public.provision_restaurant(text,text,text,text) to authenticated;
create unique index if not exists restaurants_domain_unique_idx on public.restaurants(lower(domain)) where domain is not null;
